var frag=`
#ifdef GL_ES
  precision highp float;
#endif
#define PI 3.14159265358979
uniform vec2 iResolution;
uniform vec2 iMouse;
uniform float iTime;
vec3 matcolors[4];
vec3 lightpos;

float rnd1 (vec2 p){
return fract(sin(dot(p + iTime * 0.001, vec2(14.9898,78.233))) * 43758.5453);
}
//distance functions see http://iquilezles.org/www/articles/distfunctions/distfunctions.htm
float sdSphere( vec3 p, float s )
{
  return length(p)-s;
}
float sdPlane( vec3 p )
{
	return p.y;
}
//Union
vec2 opU( vec2 d1, vec2 d2 )
{
    if(d1.x<d2.x)return d1;
else return d2;
}
//Substraction
float opS( float d1, float d2 )
{
    return max(-d1,d2);
}
//Intersection
float opI( float d1, float d2 )
{
    return max(d1,d2);
}

//definition of the world as a distance function
vec2 map(in vec3 q) {
	vec2 m=opU(opU(vec2(opS(sdSphere(q,1.0),sdSphere(q+vec3(.3,0.0,0.0),1.0)),0),vec2(opS(sdSphere(q,.4),sdSphere(q+vec3(.3,0.0,0.0),.4)),1)),vec2(sdSphere(q,.2),2));
  	m=opU(m,vec2(sdPlane(q+vec3(0.0,1.0,0.0)), 1.5)); 
		//light ball visualisation
		//m=opU(m,vec2(sdSphere(q-lightpos+.3*vec3(rnd1(5.0*q.xz),rnd1(8.0*q.xy),rnd1(7.0*q.yz)),.2),3)); 
    return m;
}

//find intersection between world's objects and ray from the camera by sphere tracing see here: http://graphics.cs.illinois.edu/sites/default/files/zeno.pdf
vec2 castRay( in vec3 ro, in vec3 rd )
{
  float mindepth = 0.0;//min depth
  float maxdepth =15.0;//max depth     
	float precis = 0.0001;//precision
    float depth = mindepth;//start at camera position
    float m = -1.0;
    for( int i=0; i<64; i++ )//64 iterations only would have to be increased for more detailed geometry
    {
	    vec2 res = map( ro+rd*depth );//return the minimum distance from point at this depth to the world
      if( res.x<precis || depth>maxdepth ) break;// if we're close enough to the world or if we've been too far
      depth += res.x;//if not, we get deeper
	    m = res.y;// m stores additional info, like material index 
    }
    if( depth>maxdepth ) m=-1.0;
    return vec2( depth, m );// return intersection depth and additional info
}

//calculate a shadowfactor by sphere tracing from light to object, see here: http://www.iquilezles.org/www/articles/rmshadows/rmshadows.htm
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<64; i++ )
    {
		float h = map( ro + rd*t ).x;
        res = min( res, 32.0*h/t );//32.0 is the shadow "resolution" shadows will be softer if diminished
        t += h;//clamp( h, 0.01, 0.10 );
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0.0, 1.0 );
}

//calculate normal vector for each point we reach
vec3 calcNormal( in vec3 pos )
{
	vec3 eps = vec3( 0.001, 0.0, 0.0 );
	vec3 nor = vec3(
	    map(pos+eps.xyy).x - map(pos-eps.xyy).x,
	    map(pos+eps.yxy).x - map(pos-eps.yxy).x,
	    map(pos+eps.yyx).x - map(pos-eps.yyx).x );
	return normalize(nor);
}

//Uick ambient occlusion approximation
float calcAO( in vec3 pos, in vec3 nor )
{
	float occ = 0.0;
    float sca = 1.0;
    for( int i=0; i<5; i++ )
    {
        float hr = 0.01 + 0.12*float(i)/4.0;
        vec3 aopos =  nor * hr + pos;
        float dd = map( aopos ).x;
        occ += -(dd-hr)*sca;
        sca *= 0.95;
    }
    return clamp( 1.0 - 3.0*occ, 0.0, 1.0 );    
}

//rendering each pixel 
vec3 render( in vec3 ro, in vec3 rd )
{ 
  vec3 col = vec3(0.8, 0.9, 1.0);
  vec2 res = castRay(ro,rd);//cast a ray from the camera to find the intersection with our world

  float t = res.x;//depth of the intersecting point
	float m = res.y;//additional info (here:material index)
	int colorindex = int(m);
    if( m>=0.0)// we touched an object, different from the plane 
    {
        vec3 pos = ro + t*rd;		//intersection point location
        vec3 nor = calcNormal( pos );//get its normal
        vec3 ref = reflect( rd, nor );//and its relexion

        // material        
         if( m==1.5)col =vec3(mod(floor(pos.x * 4.0) + floor(pos.z * 4.0), 2.0) < 1.0 ? 1.0 : 0.4); //plane checkers
				else if(colorindex==0)col = matcolors[0];//large half sphere
				else if(colorindex==1)col = matcolors[1];//medium half sphere
				else if(colorindex==2)col = matcolors[2];//small sphere
        // lighting        
    float occ = calcAO( pos, nor );//get ambient occlusion
		vec3  lig = normalize( lightpos );
		float amb = clamp( 0.5+0.5*nor.y, 0.0, 1.0 );//ambient light component
    float dif = clamp( dot( nor, lig ), 0.0, 1.0 );//diffuse light component
    float bac = clamp( dot( nor, normalize(vec3(-lig.x,0.0,-lig.z))), 0.0, 1.0 )*clamp( 1.0-pos.y,0.0,1.0);
    float dom = smoothstep( -0.1, 0.1, ref.y );//
    float fre = pow( clamp(1.0+dot(nor,rd),0.0,1.0), 2.0 );// light component
		float spe = pow(clamp( dot( ref, lig ), 0.0, 1.0 ),26.0);//specular light component
        dif *= softshadow( pos, lig, 0.3, 2.5 );//apply shaows
        dom *= softshadow( pos, ref, 0.3, 2.5 );
		vec3 brdf = vec3(0.0);//accumulate the light components
        brdf += .5*dif*vec3(1.00,0.90,0.60);
				brdf += 1.20*spe*vec3(1.00,0.90,0.60)*dif;
        brdf += 0.30*amb*vec3(0.50,0.70,1.00)*occ;
        brdf += 0.40*dom*vec3(0.50,0.70,1.00)*occ;
        brdf += 0.30*bac*vec3(0.25,0.25,0.25)*occ;
        brdf += 0.40*fre*vec3(1.00,1.00,1.00)*occ;
		//brdf += 0.02;
		col = col*brdf;
    	col = mix( col, vec3(0.8,0.9,1.0), 1.0-exp( -0.005*t*t ) );
    }
    else if(colorindex!=3){
						t /= 15.0;
						col *= exp( -0.015*t*t );}
		else col=matcolors[3];

    // lights
        vec3 lv = normalize(lightpos)- ro/3.5;
        float ll = length( lv );
        if( ll<t )
        {
        float dle = clamp( dot( rd, lv/ll), 0.0, 1.0 );
			  dle = (1.0-smoothstep( 0.0, 0.2*(0.7+0.3*.5), acos(dle)*ll ));
        col += dle*6.0*.5*vec3(1.0,1.0,0.0)*dle*exp( -0.1*ll*ll );
        }
	return vec3( clamp(col,0.0,1.0) );
}  

mat3 setCamera( in vec3 ro, in vec3 ta, float cr )

{
	vec3 cw = normalize(ta-ro);
	vec3 cp = vec3(sin(cr), cos(cr),0.0);
	vec3 cu = normalize( cross(cw,cp) );
	vec3 cv = normalize( cross(cu,cw) );
    return mat3( cu, cv, cw );        // ******** set -cv before saving image or thumb, then cv
}


void main()
{
	matcolors[0]=vec3(1.0,0.0,0.0);
	matcolors[1]=vec3(0.0,1.0,0.0);
	matcolors[2]=vec3(1.0,0.0,1.0);
	matcolors[3]=vec3(1.0,1.0,0.0);
	lightpos=vec3(8.0*sin(iTime/3.0),4.5+4.0*sin(iTime/8.0), 8.0*cos(iTime/3.0));
	vec2 q = gl_FragCoord.xy/iResolution.xy;
  vec2 p = -1.0+2.0*q;
	p.x *= iResolution.x/iResolution.y;
    vec2 mo = .5-iMouse.xy/iResolution.xy;

	float time = 15.0 + iTime;

	// camera	
	vec3 ro = vec3(6.0*sin(2.0*mo.x*PI)*(mo.y+.7),.4,2.0*cos(2.0*mo.x*PI)*(mo.y+.7));
	vec3 ta = vec3( 0.0, -1.4, 0.0 );
	// camera-to-world transformation
    mat3 ca = setCamera( ro, ta, 0.0 );

    // ray direction
	vec3 rd = ca * normalize( vec3(p.xy,2.0) );

    // render	
    vec3 col = render( ro, rd );

	col = pow( col, vec3(0.4545) );
    gl_FragColor=vec4( col, 1.0 );
}
`
var vert=`
//standard vertex shader
#ifdef GL_ES
      precision highp float;
    #endif
		#extension GL_OES_standard_derivatives : enable
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;

